/** Fills a label's {0}, {1} ... with the values given: format(LABELS.itemsMany, 12). */
export function format(text, ...values) {
  return String(text).replace(/\{(\d+)\}/g, (match, i) => (values[i] === undefined ? match : String(values[i])));
}
